class HeavyObject {
    int* buffer;
public:
    HeavyObject() : buffer(new int[1000]) {}
    ~HeavyObject() { delete[] buffer; }

    // Move Constructor: Transfers ownership
    HeavyObject(HeavyObject&& other) noexcept
        : buffer(other.buffer) {
        other.buffer = nullptr; // Source is nullified
    }

    // Move Assignment Operator
    HeavyObject& operator=(HeavyObject&& other) noexcept {
        if (this != &other) {
            delete[] buffer; // Release existing resource
            buffer = other.buffer;
            other.buffer = nullptr;
        }
        return *this;
    }
};

HeavyObject create() {
    return HeavyObject(); // RVO/Move Semantics utilized
}
